'use strict';
const $=s=>document.querySelector(s),rad=d=>d*Math.PI/180,cfg=window.COURSE_CONFIG;
let current,pendingSeek=null,pendingPlay=false,iv=null,observer=null,exportDoc=null;
function canvas(id){const e=$(id),width=e.clientWidth;e.width=Math.round(width*2);e.height=Math.round(e.clientHeight*2);const c=e.getContext('2d');c.scale(2,2);c.clearRect(0,0,width,e.clientHeight);c.font='14px Arial';c.lineWidth=2;return {c,w:width,h:e.clientHeight};}
function arrow(c,x0,y0,x1,y1,color,label){const a=Math.atan2(y1-y0,x1-x0);c.strokeStyle=color;c.fillStyle=color;c.beginPath();c.moveTo(x0,y0);c.lineTo(x1,y1);c.stroke();c.beginPath();c.moveTo(x1,y1);c.lineTo(x1-10*Math.cos(a-.4),y1-10*Math.sin(a-.4));c.lineTo(x1-10*Math.cos(a+.4),y1-10*Math.sin(a+.4));c.fill();c.fillText(label,x1+8,y1-7);}
function draw(){const {c,w,h}=canvas('#bloch'),cx=w*.49,cy=h*.51,R=Math.min(w*.31,h*.36);const project=v=>[cx+R*(v[0]-.43*v[1]),cy-R*(v[2]-.22*v[1])];c.strokeStyle='#d6ddd5';c.beginPath();c.arc(cx,cy,R,0,2*Math.PI);c.stroke();c.beginPath();c.ellipse(cx,cy,R,R*.27,0,0,2*Math.PI);c.stroke();for(const [v,label] of [[[1,0,0],'x'],[[0,1,0],'y'],[[0,0,1],'z']]){const p=project(v);arrow(c,cx,cy,...p,'#8b9c9e',label);}arrow(c,cx,cy,...project(current.r),'#067c73','state r');arrow(c,cx,cy,...project(current.n),'#ac6c1d','axis n');c.fillStyle='#536a72';c.fillText('Abstract Bloch representation',12,20);
 const a=canvas('#phasePlot'),left=45,right=a.w-20,top=25,bottom=a.h-45,xx=f=>left+f/(2*Math.PI)*(right-left),yy=p=>bottom-p*(bottom-top);a.c.strokeStyle='#d6ddd5';a.c.beginPath();a.c.moveTo(left,top);a.c.lineTo(left,bottom);a.c.lineTo(right,bottom);a.c.stroke();a.c.fillStyle='#536a72';for(const p of [0,.5,1])a.c.fillText(String(p),8,yy(p)+5);for(const d of [0,180,360])a.c.fillText(String(d)+'°',Math.min(right-30,xx(rad(d))-10),bottom+23);const pop=+$('#population').value;for(const [type,color] of [['x','#067c73'],['z','#ac6c1d']]){a.c.strokeStyle=color;a.c.beginPath();for(let i=0;i<=160;i++){const f=2*Math.PI*i/160,p=type==='x'?.5+Math.sqrt(pop*(1-pop))*Math.cos(f):pop;i?a.c.lineTo(xx(f),yy(p)):a.c.moveTo(xx(f),yy(p));}a.c.stroke();}a.c.fillStyle='#067c73';a.c.fillText('x+ probability',left+6,16);a.c.fillStyle='#ac6c1d';a.c.fillText('z+ probability',left+135,16);const phi=rad(+$('#phase').value);a.c.fillStyle='#067c73';a.c.beginPath();a.c.arc(xx(phi),yy(.5+Math.sqrt(pop*(1-pop))*Math.cos(phi)),4,0,2*Math.PI);a.c.fill();}
function update(){const p=+$('#population').value,phi=rad(+$('#phase').value),alpha=rad(+$('#polar').value),beta=rad(+$('#azimuth').value);current=Quantum.predict(p,phi,alpha,beta);$('#populationOut').textContent=p.toFixed(2);for(const id of ['phase','polar','azimuth'])$('#'+id+'Out').textContent=(+$('#'+id).value).toFixed(1)+'°';$('#probability').textContent=current.plus.toFixed(6);$('#expectation').textContent=current.spinOverHbar.toFixed(6);$('#normalization').textContent=(current.plus+current.minus).toFixed(6);draw();}
for(const id of ['population','phase','polar','azimuth'])$('#'+id).addEventListener('input',update);
document.querySelectorAll('[data-axis]').forEach(b=>b.onclick=()=>{$('#polar').value=b.dataset.axis==='z'?0:90;$('#azimuth').value=b.dataset.axis==='y'?90:0;update();});
$('#rotate').onclick=()=>{$('#phase').value=(+$('#phase').value+180)%360;update();$('#operationFeedback').textContent='Applied the relative-phase change of an ideal unitary z rotation through π; z populations remain fixed.';};
$('#condition').onclick=()=>{if(current.plus<1e-12){$('#operationFeedback').textContent='This outcome has zero probability, so there is no conditional state.';return;}$('#population').value=(1+current.n[2])/2;$('#phase').value=((Math.atan2(current.n[1],current.n[0])*180/Math.PI)+360)%360;update();$('#operationFeedback').textContent='Conditioned on a recorded + outcome: the preparation is now the + eigenstate of the selected measurement axis. Displayed angles and populations are rounded; calculations retain full precision.';};
$('#reset').onclick=()=>{for(const [id,value] of Object.entries({population:.6,phase:60,polar:0,azimuth:0}))$('#'+id).value=value;update();$('#operationFeedback').textContent='Reset to the original preparation. Choosing an observable alone does not perform a measurement.';};
$('#controls').onsubmit=e=>e.preventDefault();window.addEventListener('resize',draw);update();
$('#repositoryLink').href='https://github.com/'+cfg.repository;
if(window.katex)document.querySelectorAll('[data-math]').forEach(el=>katex.render(el.dataset.math,el,{throwOnError:true,displayMode:true}));
const frame=$('#lectureH5p');if(cfg.youtube_url){$('#videoPending').hidden=true;frame.hidden=false;frame.src='h5p/formalism.html?v='+cfg.video_revision;$('#youtubeLink').href=cfg.youtube_url;$('#youtubeLink').hidden=false;$('#h5pDownload').hidden=false;}
function connect(){if(frame.hidden)return;const doc=frame.contentDocument;if(!doc?.body)return;if(doc!==exportDoc){exportDoc=doc;if(observer)observer.disconnect();observer=new ResizeObserver(resize);observer.observe(doc.body);}const instance=frame.contentWindow.H5P?.instances?.[0];if(instance&&iv!==instance){iv=instance;iv.on('resize',resize);}resize();if(iv?.video?.getDuration?.()>0){if(pendingSeek!==null){iv.seek(pendingSeek);pendingSeek=null;}if(pendingPlay){iv.play();pendingPlay=false;}}}
function resize(){const content=exportDoc?.querySelector('.h5p-content');if(!content)return;const height=Math.ceil(content.getBoundingClientRect().height)+2;if(height>100&&Math.abs(height-frame.getBoundingClientRect().height)>1)frame.style.height=height+'px';}
frame.addEventListener('load',connect);const timer=setInterval(connect,250);window.addEventListener('pagehide',()=>{clearInterval(timer);observer?.disconnect();},{once:true});
fetch('publication_events.json').then(r=>r.json()).then(events=>{for(const c of events.chapters){const button=document.createElement('button');button.type='button';const t=Math.floor(c.start_seconds);button.innerHTML='<span class="time">'+String(Math.floor(t/60)).padStart(2,'0')+':'+String(t%60).padStart(2,'0')+'</span>';button.append(document.createTextNode(c.title));button.onclick=()=>{if(!cfg.youtube_url){$('#chapterFeedback').textContent='Public video upload is pending. Use the local preview during production.';return;}pendingSeek=c.start_seconds;pendingPlay=true;connect();};$('#chapters').append(button);}for(const q of events.quizzes){const link=document.createElement('a');link.href='h5p/question-'+q.id.slice(1)+'.html';const small=document.createElement('small');small.textContent=q.id+' / ORIGINAL FORMATIVE ACTIVITY';link.append(small,document.createTextNode(events.chapters[Math.floor(q.scene/4)].title));$('#practiceLinks').append(link);}}).catch(e=>{$('#chapterFeedback').textContent='Course metadata could not load: '+e.message;});
